def findMaximumNum(s, k):
    def helper(s, k, max_num):
        if k == 0:
            return max_num
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n):
                if s[i] < s[j]:
                    new_s = s[:i] + s[j] + s[i + 1:j] + s[i] + s[j + 1:]
                    if new_s > max_num:
                        max_num = new_s
                    max_num = helper(new_s, k - 1, max_num)
        return max_num

    return helper(s, k, s)
